import{_ as a,o,c,a2 as t}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"进程调度","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/scheduler.md","filePath":"zh/arch/scheduler.md"}'),d={name:"zh/arch/scheduler.md"};function r(s,e,h,n,l,i){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="进程调度" tabindex="-1">进程调度 <a class="header-anchor" href="#进程调度" aria-label="Permalink to &quot;进程调度&quot;">​</a></h1><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p><code>kernel/core/core_sched.{c,h}</code>：采用抢占式、基于优先级的调度，同一优先级内采用时间片轮转。任务控制块（TCB）保存状态、优先级、时间片以及保存的帧；上下文切换（<code>arch/x86_64/arch_context_switch.S</code>）通过了 ABI 探测验证（在调度调用处保持 SysV 16 字节栈对齐 - BUG-0137）。</p><h2 id="节拍" tabindex="-1">节拍 <a class="header-anchor" href="#节拍" aria-label="Permalink to &quot;节拍&quot;">​</a></h2><p>PIT 以 100 Hz 的频率触发 IRQ0：节拍计数器、<code>g_boot_time_ms</code>、软定时器轮以及调度器的抢占均依赖于此。<code>sched</code>、<code>ps</code>、<code>nice</code>、<code>sleep</code>、<code>kill</code>、<code>spawn</code>、<code>multi</code> 是面向用户的命令。</p><h2 id="后台任务与策略看门狗" tabindex="-1">后台任务与策略看门狗 <a class="header-anchor" href="#后台任务与策略看门狗" aria-label="Permalink to &quot;后台任务与策略看门狗&quot;">​</a></h2><p>长时间运行的工作（<code>g6_test &amp;</code>、自旋任务）作为后台任务运行。看门狗子系统（<code>kernel/core/core_watchdog.c</code>）添加了监控槽位：必须为其槽位&quot;喂狗&quot;的任务若停止执行，则会被终止并记录原因，同时内核本身保持存活。硬件看门狗（TCO/WDAT）则保护整个机器：参见 <a href="./../internals/watchdog.html">内部机制：看门狗子系统</a>。</p><h2 id="信号与进程" tabindex="-1">信号与进程 <a class="header-anchor" href="#信号与进程" aria-label="Permalink to &quot;信号与进程&quot;">​</a></h2><p>Ring-3 进程通过系统调用接口接收信号；用户测试程序（<code>run signal_test</code>、<code>run fork_test</code>、<code>run exec_test</code>、<code>run pipe_test</code>、<code>run select_test</code>）展示了完整的 Unix 风格进程模型：fork、exec、管道、select、mmap。</p>',9)])])}const p=a(d,[["render",r]]);export{u as __pageData,p as default};
